-- AssembleHumanBody (generated by build_human.py): run once in Studio's command bar after importing
-- NeonCoastHuman.fbx with the 3D Importer (rig: R15). Select the imported model, paste this, press Enter.
-- It finishes the character: Humanoid settings, the root part, standard attachments (tools, hats), the NC_Body
-- tag the movement scripts look for, and puts it in StarterPlayer as StarterCharacter so everyone spawns as it.
local model = game:GetService("Selection"):Get()[1]
assert(model and model:IsA("Model"), "Select the imported NeonCoastHuman model first")
local REST_HRP_Y = 3.700 -- root part centre above the ground in the rest pose
local HIP_HEIGHT = 2.700
local ATT = {
	{ "Head", "HatAttachment", Vector3.new(0.000, 6.620, -0.020) },
	{ "Head", "HairAttachment", Vector3.new(0.000, 6.580, 0.000) },
	{ "Head", "FaceFrontAttachment", Vector3.new(0.000, 6.200, -0.420) },
	{ "Head", "FaceCenterAttachment", Vector3.new(0.000, 6.200, -0.040) },
	{ "UpperTorso", "NeckAttachment", Vector3.new(0.000, 5.620, 0.060) },
	{ "UpperTorso", "BodyFrontAttachment", Vector3.new(0.000, 5.000, -0.450) },
	{ "UpperTorso", "BodyBackAttachment", Vector3.new(0.000, 5.000, 0.480) },
	{ "UpperTorso", "LeftCollarAttachment", Vector3.new(-0.450, 5.500, 0.040) },
	{ "UpperTorso", "RightCollarAttachment", Vector3.new(0.450, 5.500, 0.040) },
	{ "LowerTorso", "WaistCenterAttachment", Vector3.new(0.000, 4.200, 0.050) },
	{ "LowerTorso", "WaistFrontAttachment", Vector3.new(0.000, 4.200, -0.380) },
	{ "LowerTorso", "WaistBackAttachment", Vector3.new(0.000, 4.200, 0.420) },
	{ "RightHand", "RightGripAttachment", Vector3.new(1.151, 2.858, 0.030) },
	{ "RightUpperArm", "RightShoulderAttachment", Vector3.new(0.860, 5.510, 0.030) },
	{ "RightFoot", "RightFootAttachment", Vector3.new(0.370, 0.000, -0.100) },
	{ "LeftHand", "LeftGripAttachment", Vector3.new(-1.151, 2.858, 0.030) },
	{ "LeftUpperArm", "LeftShoulderAttachment", Vector3.new(-0.860, 5.510, 0.030) },
	{ "LeftFoot", "LeftFootAttachment", Vector3.new(-0.370, 0.000, -0.100) },
}
local need = { "HumanoidRootPart", "LowerTorso", "UpperTorso", "Head", "LeftUpperArm", "LeftLowerArm", "LeftHand",
	"RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
for _, n in need do
	if not model:FindFirstChild(n) then
		warn("AssembleHumanBody: missing " .. n .. " (import with the R15 rig option)")
	end
end
local hrp = model:FindFirstChild("HumanoidRootPart")
assert(hrp, "no HumanoidRootPart: import with the R15 rig option")
hrp.Size, hrp.Transparency, hrp.CanCollide = Vector3.new(2, 2, 1), 1, true
model.PrimaryPart = hrp
local hum = model:FindFirstChildOfClass("Humanoid") or Instance.new("Humanoid")
hum.Parent = model
hum.RigType = Enum.HumanoidRigType.R15
pcall(function() hum.AutomaticScalingEnabled = false end)
hum.HipHeight = HIP_HEIGHT
-- the ground point under the root part in the rest pose, facing the model's way
local origin = hrp.CFrame * CFrame.new(0, -REST_HRP_Y, 0)
for _, a in ATT do
	local part = model:FindFirstChild(a[1])
	if part and not part:FindFirstChild(a[2]) then
		local at = Instance.new("Attachment")
		at.Name = a[2]
		at.WorldCFrame = origin * CFrame.new(a[3])
		at.Parent = part
	end
end
for _, d in model:GetDescendants() do
	if d:IsA("MeshPart") and d ~= hrp then
		d.CanCollide = d.Name == "UpperTorso" or d.Name == "LowerTorso" or d.Name == "Head"
		pcall(function() d.CollisionFidelity = Enum.CollisionFidelity.Box end)
		d.Anchored = false
	end
end
hrp.Anchored = false
model:SetAttribute("NC_Body", "Human")
model.Name = "StarterCharacter"
model.Parent = game:GetService("StarterPlayer")
print("AssembleHumanBody: done. StarterPlayer.StarterCharacter is the Neon Coast human body (" .. #model:GetDescendants() .. " parts and joints).")
